results.content:
else:
            child1, child2 = self._children
            eq1 = child1.to_equation()
            eq2 = child2.to_equation()
            return self._sympy_operator(eq1, eq2)

    def to_json(self):
        """
        Method to serialise a BinaryOperator object into JSON.
        """

        json_dict = {"name": self.name, "domains": self.domains}

        return json_dict

    def _t_discon(self, expr, y0, inputs, num_events):
        """Returns the discontinuity time-points for a function."""
        raise NotImplementedError(f"`_t_discon` not implemented for {self.name}")


class Power(BinaryOperator):
    """
    A node in the expression tree representing a `**` power operator.
    """

    __slots__ = ()
    DISCONTINUITY event will automatically be added by the solver.
    """

    __slots__ = ()

    def __init__(
        self,
        name: str,
        left: ChildSymbol,
        right: ChildSymbol,
    ):
        """See :meth:`pybamm.BinaryOperator.__init__()`."""
        super().__init__(name, left, right)

    def diff(self, variable):
        """See :meth:`pybamm.Symbol.diff()`."""
        # Heaviside should always be multiplied by something else so hopefully don't
        # need to worry about shape
        return pybamm.Scalar(0)

    def _binary_jac(self, left_jac, right_jac):
        """See :meth:`pybamm.BinaryOperator._binary_jac()`."""
        # Heaviside should always be multiplied by something else so hopefully don't
        # need to worry about shape
        return pybamm.Scalar(0)

    def _evaluate_for_shape(self):
        """
        Returns an array of NaNs of the correct shape.
        See :meth:`pybamm.Symbol.evaluate_for_shape()`.
        """
        left = self._children[0].evaluate_for_shape()
        right = self._children[1].evaluate_for_shape()
        # _binary_evaluate will return an array of bools, so we multiply by NaN to get
        # an array of NaNs
        return self._binary_evaluate(left, right) * np.nan

    def _t_discon(self, expr, y0, inputs, num_events):
        """Returns the discontinuity time-points for the heaviside function."""
        value = expr.evaluate(0, y0, inputs=inputs)
        t_discon = [value]
        t_discon.append(self._t_discon_next(value))
        return t_discon

    def _t_discon_next(self, value: float):
        raise NotImplementedError(
            "_t_discon_next method should be implemented in subclasses of _Heaviside"
        )  # pragma: no cover


class EqualHeaviside(_Heaviside):
    """A heaviside function with equality (return 1 when left = right)"""

    __slots__ = ()

    def __init__(
        self,
        left: ChildSymbol,
        right: ChildSymbol,
    ):
        """See :meth:`pybamm.BinaryOperator.__init__()`."""
        super().__init__("<=", left, right)

    def __str__(self):
        """See :meth:`pybamm.Symbol.__str__()`."""
        return f"{self.left!s} <= {self.right!s}"

    def _binary_evaluate(self, left, right):
        """See :meth:`pybamm.BinaryOperator._binary_evaluate()`."""
        # don't raise RuntimeWarning for NaNs
        with np.errstate(invalid="ignore"):
            return left <= right

    def _t_discon_next(self, value: float):
        if self.left == pybamm.t:
            # t <= x
            # Stop at t = x and right after t = x
            return np.nextafter(value, np.inf)
        else:
            # t >= x
            # Stop at t = x and right before t = x
            return np.nextafter(value, -np.inf)


class NotEqualHeaviside(_Heaviside):
    """A heaviside function without equality (return 0 when left = right)"""

    __slots__ = ()

    def __init__(
        self,
        left: ChildSymbol,
        right: ChildSymbol,
    ):
        super().__init__("<", left, right)

    def __str__(self):
        """See :meth:`pybamm.Symbol.__str__()`."""
        return f"{self.left!s} < {self.right!s}"

    def _binary_evaluate(self, left, right):
        """See :meth:`pybamm.BinaryOperator._binary_evaluate()`."""
        # don't raise RuntimeWarning for NaNs
        with np.errstate(invalid="ignore"):
            return left < right

    def _t_discon_next(self, value: float):
        if self.left == pybamm.t:
            # t < x
            # Stop at t = x and right before t = x
            return np.nextafter(value, -np.inf)
        else:
            # t > x
            # Stop at t = x and right after t = x
            return np.nextafter(value, np.inf)


class Modulo(BinaryOperator):
    """Calculates the remainder of an integer division."""

    __slots__ = ()

    def __init__(
        self,
        left: ChildSymbol,
        right: ChildSymbol,
    ):
        super().__init__("%", left, right)

    def _diff(self, variable: pybamm.Symbol):
        """See :meth:`pybamm.Symbol._diff()`."""
        # apply chain rule and power rule
        left, right = self.orphans
        # derivative if variable is in the base
        diff = left.diff(variable)
        # derivative if variable is in the right term (rare, check separately to avoid
        # unecessarily big tree)
        if any(variable == x for x in right.pre_order()):
            diff += -pybamm.Floor(left / right) * right.diff(variable)
        return diff

    def _binary_jac(self, left_jac, right_jac):
        """See :meth:`pybamm.BinaryOperator._binary_jac()`."""
        # apply chain rule and power rule
        left, right = self.orphans
        if right.evaluates_to_constant_number():
            return left_jac
        elif left.evaluates_to_constant_number():
            return -right_jac * pybamm.Floor(left / right)
        else:
            return left_jac - right_jac * pybamm.Floor(left / right)

    def __str__(self):
        """See :meth:`pybamm.Symbol.__str__()`."""
        return f"{self.left!s} mod {self.right!s}"

    def _binary_evaluate(self, left, right):
        """See :meth:`pybamm.BinaryOperator._binary_evaluate()`."""
        return left % right

    def _casadi_evaluate(self, left, right):
        """See :meth:`pybamm.BinaryOperator._casadi_evaluate()`."""
        return casadi.fmod(left, right)

    def _t_discon(self, expr, y0, inputs, num_events):
        value = expr.evaluate(0, y0, inputs=inputs)
        t_discon = []

        for i in np.arange(num_events):
            t = value * (i + 1)
            # Stop right before t and at t
            t_discon.append(np.nextafter(t, -np.inf))
            t_discon.append(t)
        return t_discon


class Minimum(BinaryOperator):
    """Returns the smaller of two objects."""

    __slots__ = ()

    def __init__(
        self,
        left: ChildSymbol,
        right: ChildSymbol,
    ):
        super().__init__("minimum", left, right)

    def __str__(self):
        """See :meth:`pybamm.Symbol.__str__()`."""
        return f"minimum({self.left!s}, {self.right!s})"

    def _diff(self, variable: pybamm.Symbol):
        """See :meth:`pybamm.Symbol._diff()`."""
        left, right = self.orphans
        return (left <= right) * left.diff(variable) + (left > right) * right.diff(
            variable
        )

    def _binary_jac(self, left_jac, right_jac):
        """See :meth:`pybamm.BinaryOperator._binary_jac()`."""
        left, right = self.orphans
        return (left <= right) * left_jac + (left > right) * right_jac

    def _binary_evaluate(self, left, right):
        """See :meth:`pybamm.BinaryOperator._binary_evaluate()`."""
        # don't raise RuntimeWarning for NaNs
        return np.minimum(left, right)

    def _casadi_evaluate(self, left, right):
        """See :meth:`pybamm.BinaryOperator._casadi_evaluate()`."""

